import java.util.Scanner

fun min(a: Long, b: Long): Long = if (a > b) b else a

fun main() {
    val scanner = Scanner(System.`in`)
    var l = scanner.nextLong()
    val r = scanner.nextLong()

    val a = LongArray(11)
    var x = 0L
    var j = 1L

    while (j <= r) {
        var i = 10
        a[i]++
        while (a[i] > 2) {
            a[i] = 0
            i--
            a[i]++
        }
        j = 0
        i = 1
        while (i <= 10) {
            if (j > 0 && a[i] == 0) {
                break
            }
            val n1 = if (a[i] == 1) 4L else 0L
            val n2 = if (a[i] == 2) 7L else 0L
            j = j * 10 + n1 + n2
            i++
        }
        if (x == 0L && j >= l) {
            x += j
        }
        if (i <= 10) {
            continue
        }
        if (j >= l) {
            x += (min(j, r) - l) * j
            l = j
        }
    }
    print(x)
}

